-- Empty independent CRM schema; contains no source users or business rows.

create schema if not exists app_private;

set check_function_bodies = off;

create sequence public."customer_code_seq" as bigint start 1 increment 1;

create table public."trades" (
 "id" bigint generated by default as identity not null,
 "customer_id" bigint not null,
 "entered_by" uuid not null,
 "symbol" text not null,
 "stock_name" text,
 "market" text not null,
 "side" text not null,
 "quantity" numeric(20,6) not null,
 "price" numeric(20,6) not null,
 "currency" text default 'USD'::text not null,
 "fees" numeric(20,6) default 0 not null,
 "traded_at" timestamp with time zone not null,
 "note" text,
 "created_at" timestamp with time zone default now() not null
);

create table public."customers" (
 "id" bigint generated by default as identity not null,
 "customer_code" text default ((('C'::text || to_char(now(), 'YYYYMMDD'::text)) || '-'::text) || lpad((nextval('customer_code_seq'::regclass))::text, 5, '0'::text)) not null,
 "owner_user_id" uuid not null,
 "level_one_user_id" uuid not null,
 "name" text not null,
 "phone" text,
 "email" text,
 "region" text,
 "status" text default 'prospect'::text not null,
 "risk_level" text default 'normal'::text not null,
 "notes" text,
 "created_at" timestamp with time zone default now() not null,
 "updated_at" timestamp with time zone default now() not null,
 "gender" text default 'unknown'::text not null,
 "age" smallint,
 "capital_amount" numeric(18,2),
 "capital_currency" text default 'USD'::text not null
);

create table public."positions" (
 "customer_id" bigint not null,
 "symbol" text not null,
 "market" text not null,
 "stock_name" text,
 "currency" text default 'USD'::text not null,
 "quantity" numeric(20,6) default 0 not null,
 "avg_cost" numeric(20,6) default 0 not null,
 "total_bought" numeric(20,6) default 0 not null,
 "total_sold" numeric(20,6) default 0 not null,
 "realized_pnl" numeric(20,6) default 0 not null,
 "updated_at" timestamp with time zone default now() not null
);

create table public."customer_followups" (
 "id" bigint generated by default as identity not null,
 "customer_id" bigint not null,
 "user_id" uuid not null,
 "channel" text default 'other'::text not null,
 "content" text not null,
 "next_followup_at" timestamp with time zone,
 "created_at" timestamp with time zone default now() not null
);

create table public."audit_logs" (
 "id" bigint generated by default as identity not null,
 "user_id" uuid,
 "action" text not null,
 "entity_type" text not null,
 "entity_id" text,
 "metadata" jsonb,
 "created_at" timestamp with time zone default now() not null
);

create table public."profiles" (
 "id" uuid not null,
 "username" text not null,
 "display_name" text not null,
 "role" text not null,
 "parent_user_id" uuid,
 "status" text default 'active'::text not null,
 "phone" text,
 "created_at" timestamp with time zone default now() not null,
 "updated_at" timestamp with time zone default now() not null
);

create table public."system_config" (
 "key" text not null,
 "value" text not null,
 "updated_at" timestamp with time zone default now() not null
);

create table public."share_board_slots" (
 "id" uuid default gen_random_uuid() not null,
 "board_id" uuid not null,
 "slot_at" timestamp with time zone not null,
 "reserved_shares" numeric(20,4) default 0 not null,
 "participant_count" integer default 0 not null,
 "created_at" timestamp with time zone default now() not null
);

create table public."share_boards" (
 "id" uuid default gen_random_uuid() not null,
 "symbol" text not null,
 "stock_name" text,
 "company_name" text,
 "exchange" text,
 "market" text,
 "country" text,
 "currency" text,
 "industry" text,
 "total_shares" numeric(20,4) not null,
 "remaining_shares" numeric(20,4) not null,
 "board_date" date default ((now() AT TIME ZONE 'Europe/Bucharest'::text))::date not null,
 "created_by" uuid not null,
 "created_at" timestamp with time zone default now() not null,
 "updated_at" timestamp with time zone default now() not null
);

create table public."app_settings" (
 "id" smallint default 1 not null,
 "default_language" text default 'zh'::text not null,
 "romania_timezone" text default 'Europe/Bucharest'::text not null,
 "market_open_time" time without time zone default '09:30:00'::time without time zone not null,
 "target_trade_time" time without time zone default '14:30:00'::time without time zone not null,
 "share_board_refresh_seconds" integer default 60 not null,
 "energy_high" numeric(6,2) default 60 not null,
 "energy_low" numeric(6,2) default 30 not null,
 "updated_at" timestamp with time zone default now() not null
);

create table public."allocation_reservations" (
 "id" uuid default gen_random_uuid() not null,
 "project_id" uuid not null,
 "owner_user_id" uuid not null,
 "slot_at" timestamp with time zone not null,
 "reserved_shares" numeric(20,4) not null,
 "participant_count" integer default 0 not null,
 "notes" text default ''::text not null,
 "created_at" timestamp with time zone default now() not null,
 "updated_at" timestamp with time zone default now() not null
);

create table public."allocation_projects" (
 "id" uuid default gen_random_uuid() not null,
 "owner_user_id" uuid not null,
 "project_number" smallint not null,
 "name" text not null,
 "symbol" text default ''::text not null,
 "currency" text default 'USD'::text not null,
 "total_shares" numeric(20,4) not null,
 "remaining_shares" numeric(20,4) not null,
 "board_date" date default ((now() AT TIME ZONE 'Europe/Bucharest'::text))::date not null,
 "details" text default ''::text not null,
 "created_at" timestamp with time zone default now() not null,
 "updated_at" timestamp with time zone default now() not null,
 "customer_ledger_enabled" boolean default false not null
);

create table public."allocation_customer_reservations" (
 "id" uuid default gen_random_uuid() not null,
 "project_id" uuid not null,
 "owner_user_id" uuid not null,
 "customer_id" bigint not null,
 "reserved_shares" numeric(20,4) not null,
 "status" text default 'confirmed'::text not null,
 "confirmed_at" timestamp with time zone,
 "created_at" timestamp with time zone default now() not null
);

alter table public."profiles" add constraint "profiles_username_check" CHECK ((username ~ '^[A-Za-z0-9._-]{3,32}$'::text));

alter table public."profiles" add constraint "profiles_pkey" PRIMARY KEY (id);

alter table public."profiles" add constraint "profiles_username_key" UNIQUE (username);

alter table public."customers" add constraint "customers_status_check" CHECK ((status = ANY (ARRAY['prospect'::text, 'following'::text, 'holding'::text, 'closed'::text, 'archived'::text])));

alter table public."customers" add constraint "customers_risk_level_check" CHECK ((risk_level = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text])));

alter table public."customers" add constraint "customers_pkey" PRIMARY KEY (id);

alter table public."customers" add constraint "customers_customer_code_key" UNIQUE (customer_code);

alter table public."trades" add constraint "trades_side_check" CHECK ((side = ANY (ARRAY['buy'::text, 'sell'::text])));

alter table public."trades" add constraint "trades_quantity_check" CHECK ((quantity > (0)::numeric));

alter table public."trades" add constraint "trades_fees_check" CHECK ((fees >= (0)::numeric));

alter table public."trades" add constraint "trades_pkey" PRIMARY KEY (id);

alter table public."positions" add constraint "positions_pkey" PRIMARY KEY (customer_id, symbol);

alter table public."customer_followups" add constraint "customer_followups_channel_check" CHECK ((channel = ANY (ARRAY['phone'::text, 'whatsapp'::text, 'email'::text, 'meeting'::text, 'other'::text])));

alter table public."customer_followups" add constraint "customer_followups_pkey" PRIMARY KEY (id);

alter table public."audit_logs" add constraint "audit_logs_pkey" PRIMARY KEY (id);

alter table public."system_config" add constraint "system_config_pkey" PRIMARY KEY (key);

alter table public."customers" add constraint "customers_gender_check" CHECK ((gender = ANY (ARRAY['male'::text, 'female'::text, 'unknown'::text])));

alter table public."customers" add constraint "customers_age_check" CHECK (((age IS NULL) OR ((age >= 18) AND (age <= 120))));

alter table public."app_settings" add constraint "app_settings_id_check" CHECK ((id = 1));

alter table public."app_settings" add constraint "app_settings_default_language_check" CHECK ((default_language = ANY (ARRAY['zh'::text, 'en'::text, 'ro'::text])));

alter table public."app_settings" add constraint "app_settings_share_board_refresh_seconds_check" CHECK (((share_board_refresh_seconds >= 10) AND (share_board_refresh_seconds <= 3600)));

alter table public."app_settings" add constraint "app_settings_pkey" PRIMARY KEY (id);

alter table public."share_boards" add constraint "share_boards_total_shares_check" CHECK ((total_shares > (0)::numeric));

alter table public."share_boards" add constraint "share_boards_remaining_shares_check" CHECK ((remaining_shares >= (0)::numeric));

alter table public."share_boards" add constraint "share_boards_pkey" PRIMARY KEY (id);

alter table public."share_boards" add constraint "share_boards_symbol_board_date_key" UNIQUE (symbol, board_date);

alter table public."share_board_slots" add constraint "share_board_slots_reserved_shares_check" CHECK ((reserved_shares >= (0)::numeric));

alter table public."share_board_slots" add constraint "share_board_slots_participant_count_check" CHECK ((participant_count >= 0));

alter table public."share_board_slots" add constraint "share_board_slots_pkey" PRIMARY KEY (id);

alter table public."share_board_slots" add constraint "share_board_slots_board_id_slot_at_key" UNIQUE (board_id, slot_at);

alter table public."profiles" add constraint "profiles_status_check" CHECK ((status = ANY (ARRAY['active'::text, 'disabled'::text, 'pending'::text, 'deleted'::text])));

alter table public."trades" add constraint "trades_price_check" CHECK ((price > (0)::numeric));

alter table public."share_boards" add constraint "share_boards_remaining_lte_total_check" CHECK ((remaining_shares <= total_shares));

alter table public."allocation_projects" add constraint "allocation_projects_project_number_check" CHECK (((project_number >= 1) AND (project_number <= 3)));

alter table public."allocation_projects" add constraint "allocation_projects_name_check" CHECK (((char_length(btrim(name)) >= 1) AND (char_length(btrim(name)) <= 120)));

alter table public."allocation_projects" add constraint "allocation_projects_currency_check" CHECK ((currency ~ '^[A-Z]{3}$'::text));

alter table public."allocation_projects" add constraint "allocation_projects_total_shares_check" CHECK (((total_shares > (0)::numeric) AND (total_shares <> 'NaN'::numeric)));

alter table public."allocation_projects" add constraint "allocation_projects_check" CHECK (((remaining_shares >= (0)::numeric) AND (remaining_shares <= total_shares) AND (remaining_shares <> 'NaN'::numeric)));

alter table public."allocation_projects" add constraint "allocation_projects_details_check" CHECK ((char_length(details) <= 4000));

alter table public."allocation_projects" add constraint "allocation_projects_pkey" PRIMARY KEY (id);

alter table public."allocation_projects" add constraint "allocation_projects_owner_user_id_project_number_key" UNIQUE (owner_user_id, project_number);

alter table public."allocation_projects" add constraint "allocation_projects_id_owner_user_id_key" UNIQUE (id, owner_user_id);

alter table public."allocation_reservations" add constraint "allocation_reservations_reserved_shares_check" CHECK (((reserved_shares >= (0)::numeric) AND (reserved_shares <> 'NaN'::numeric)));

alter table public."allocation_reservations" add constraint "allocation_reservations_participant_count_check" CHECK ((participant_count >= 0));

alter table public."allocation_reservations" add constraint "allocation_reservations_notes_check" CHECK ((char_length(notes) <= 2000));

alter table public."allocation_reservations" add constraint "allocation_reservations_pkey" PRIMARY KEY (id);

alter table public."allocation_reservations" add constraint "allocation_reservations_project_id_slot_at_key" UNIQUE (project_id, slot_at);

alter table public."allocation_customer_reservations" add constraint "allocation_customer_reservations_reserved_shares_check" CHECK (((reserved_shares > (0)::numeric) AND (reserved_shares <> 'NaN'::numeric)));

alter table public."allocation_customer_reservations" add constraint "allocation_customer_reservations_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'cancelled'::text])));

alter table public."allocation_customer_reservations" add constraint "allocation_customer_reservations_check" CHECK ((((status = 'confirmed'::text) AND (confirmed_at IS NOT NULL)) OR ((status <> 'confirmed'::text) AND (confirmed_at IS NULL))));

alter table public."allocation_customer_reservations" add constraint "allocation_customer_reservations_pkey" PRIMARY KEY (id);

alter table public."profiles" add constraint "profiles_role_check" CHECK ((role = ANY (ARRAY['admin'::text, 'level2'::text])));

alter table public."profiles" add constraint "profile_parent_rule" CHECK ((((role = 'admin'::text) AND (parent_user_id IS NULL)) OR ((role = 'level2'::text) AND (parent_user_id IS NOT NULL))));

alter table public."profiles" add constraint "profiles_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;

alter table public."profiles" add constraint "profiles_parent_user_id_fkey" FOREIGN KEY (parent_user_id) REFERENCES profiles(id) ON DELETE SET NULL;

alter table public."customers" add constraint "customers_owner_user_id_fkey" FOREIGN KEY (owner_user_id) REFERENCES profiles(id);

alter table public."customers" add constraint "customers_level_one_user_id_fkey" FOREIGN KEY (level_one_user_id) REFERENCES profiles(id);

alter table public."trades" add constraint "trades_customer_id_fkey" FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE;

alter table public."trades" add constraint "trades_entered_by_fkey" FOREIGN KEY (entered_by) REFERENCES profiles(id);

alter table public."positions" add constraint "positions_customer_id_fkey" FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE;

alter table public."customer_followups" add constraint "customer_followups_customer_id_fkey" FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE;

alter table public."customer_followups" add constraint "customer_followups_user_id_fkey" FOREIGN KEY (user_id) REFERENCES profiles(id);

alter table public."share_boards" add constraint "share_boards_created_by_fkey" FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE RESTRICT;

alter table public."share_board_slots" add constraint "share_board_slots_board_id_fkey" FOREIGN KEY (board_id) REFERENCES share_boards(id) ON DELETE CASCADE;

alter table public."allocation_projects" add constraint "allocation_projects_owner_user_id_fkey" FOREIGN KEY (owner_user_id) REFERENCES profiles(id);

alter table public."allocation_reservations" add constraint "allocation_reservations_owner_user_id_fkey" FOREIGN KEY (owner_user_id) REFERENCES profiles(id);

alter table public."allocation_reservations" add constraint "allocation_reservations_project_id_owner_user_id_fkey" FOREIGN KEY (project_id, owner_user_id) REFERENCES allocation_projects(id, owner_user_id);

alter table public."allocation_customer_reservations" add constraint "allocation_customer_reservations_owner_user_id_fkey" FOREIGN KEY (owner_user_id) REFERENCES profiles(id);

alter table public."allocation_customer_reservations" add constraint "allocation_customer_reservations_customer_id_fkey" FOREIGN KEY (customer_id) REFERENCES customers(id);

alter table public."allocation_customer_reservations" add constraint "allocation_customer_reservations_project_id_owner_user_id_fkey" FOREIGN KEY (project_id, owner_user_id) REFERENCES allocation_projects(id, owner_user_id);

CREATE OR REPLACE FUNCTION public.sync_level2_customer_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin if new.role='level2' and (new.parent_user_id is distinct from old.parent_user_id or new.role is distinct from old.role) then
 update public.customers set level_one_user_id=new.parent_user_id where owner_user_id=new.id and level_one_user_id is distinct from new.parent_user_id;
end if;return new;end$function$
;

CREATE OR REPLACE FUNCTION app_private.can_access_customer(target_customer bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'app_private'
AS $function$
  select exists(
    select 1 from public.customers c
    where c.id = target_customer
      and app_private.can_access_owner(c.owner_user_id, c.level_one_user_id)
  );
$function$
;

CREATE OR REPLACE FUNCTION app_private.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists(
    select 1 from public.profiles
    where id = (select auth.uid()) and role='admin' and status='active'
  );
$function$
;

CREATE OR REPLACE FUNCTION app_private.audit_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id text;
begin
  v_id := coalesce(case when tg_op='DELETE' then to_jsonb(old)->>'id' else to_jsonb(new)->>'id' end,'');
  insert into public.audit_logs(user_id,action,entity_type,entity_id,metadata)
  values(
    (select auth.uid()), lower(tg_op), tg_table_name, v_id,
    jsonb_build_object(
      'old', case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,
      'new', case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end
    )
  );
  return coalesce(new,old);
end;
$function$
;

CREATE OR REPLACE FUNCTION app_private.can_access_owner(target_owner uuid, target_level_one uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'app_private'
AS $function$
 select app_private.is_admin() or (app_private.current_user_role()='level2' and target_owner=(select auth.uid()));
$function$
;

CREATE OR REPLACE FUNCTION public.audit_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id text;
begin
  v_id := coalesce(
    case when tg_op='DELETE' then to_jsonb(old)->>'id' else to_jsonb(new)->>'id' end,
    ''
  );
  insert into public.audit_logs(user_id,action,entity_type,entity_id,metadata)
  values(
    auth.uid(),
    lower(tg_op),
    tg_table_name,
    v_id,
    jsonb_build_object(
      'old', case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,
      'new', case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end
    )
  );
  return coalesce(new,old);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_share_board_slot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  b public.share_boards%rowtype;
  s public.app_settings%rowtype;
  local_date date;
  local_time time;
  cutoff time;
  existing_total numeric;
begin
  select * into b from public.share_boards where id=new.board_id;
  if not found then raise exception '股票份额看板不存在'; end if;

  select * into s from public.app_settings where id=1;
  cutoff := least(s.market_open_time,s.target_trade_time);
  local_date := (new.slot_at at time zone coalesce(s.romania_timezone,'Europe/Bucharest'))::date;
  local_time := (new.slot_at at time zone coalesce(s.romania_timezone,'Europe/Bucharest'))::time;

  if local_date <> b.board_date then
    raise exception '时段记录日期必须与看板日期一致';
  end if;
  if local_time < time '06:00' or local_time > cutoff then
    raise exception '时段记录必须位于有效业务时段内';
  end if;
  if local_date > (now() at time zone coalesce(s.romania_timezone,'Europe/Bucharest'))::date
     or (
       local_date = (now() at time zone coalesce(s.romania_timezone,'Europe/Bucharest'))::date
       and local_time > (now() at time zone coalesce(s.romania_timezone,'Europe/Bucharest'))::time
     ) then
    raise exception '不能录入未来时段数据';
  end if;

  select coalesce(sum(reserved_shares),0)
  into existing_total
  from public.share_board_slots
  where board_id=new.board_id and id is distinct from new.id;

  if existing_total + new.reserved_shares > (b.total_shares-b.remaining_shares) then
    raise exception '时段预留份额合计不能超过已预留份额';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION app_private.current_user_role()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select role from public.profiles
  where id = (select auth.uid()) and status = 'active'
  limit 1;
$function$
;

CREATE OR REPLACE FUNCTION public.can_read_allocation_owner(target_owner uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
 select exists(select 1 from public.profiles requester join public.profiles owner on owner.id=target_owner
 where requester.id=(select auth.uid()) and requester.status='active' and owner.status='active'
 and ((requester.role in ('admin','level2') and requester.id=owner.id) or (requester.role='admin' and owner.role='level2' and owner.parent_user_id=requester.id)));
$function$
;

CREATE OR REPLACE FUNCTION app_private.recalculate_position(p_customer_id bigint, p_symbol text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  v_qty numeric(20,6) := 0;
  v_avg numeric(20,6) := 0;
  v_realized numeric(20,6) := 0;
  v_total_bought numeric(20,6) := 0;
  v_total_sold numeric(20,6) := 0;
  v_market text := '';
  v_name text := null;
  v_currency text := 'USD';
begin
  for r in
    select * from public.trades
    where customer_id = p_customer_id and symbol = p_symbol
    order by traded_at asc, id asc
  loop
    v_market := r.market;
    v_name := r.stock_name;
    v_currency := r.currency;
    if r.side = 'buy' then
      if v_qty + r.quantity > 0 then
        v_avg := ((v_avg * v_qty) + (r.price * r.quantity) + r.fees) / (v_qty + r.quantity);
      end if;
      v_qty := v_qty + r.quantity;
      v_total_bought := v_total_bought + (r.price * r.quantity) + r.fees;
    else
      if r.quantity > v_qty then
        raise exception '卖出数量超过当前持仓：% > %', r.quantity, v_qty;
      end if;
      v_realized := v_realized + ((r.price - v_avg) * r.quantity) - r.fees;
      v_qty := v_qty - r.quantity;
      v_total_sold := v_total_sold + (r.price * r.quantity) - r.fees;
      if v_qty = 0 then v_avg := 0; end if;
    end if;
  end loop;

  if not exists(select 1 from public.trades where customer_id=p_customer_id and symbol=p_symbol) then
    delete from public.positions where customer_id=p_customer_id and symbol=p_symbol;
    return;
  end if;

  insert into public.positions(customer_id,symbol,market,stock_name,currency,quantity,avg_cost,total_bought,total_sold,realized_pnl,updated_at)
  values(p_customer_id,p_symbol,v_market,v_name,v_currency,v_qty,v_avg,v_total_bought,v_total_sold,v_realized,now())
  on conflict (customer_id,symbol) do update set
    market=excluded.market,stock_name=excluded.stock_name,currency=excluded.currency,
    quantity=excluded.quantity,avg_cost=excluded.avg_cost,total_bought=excluded.total_bought,
    total_sold=excluded.total_sold,realized_pnl=excluded.realized_pnl,updated_at=now();
end;
$function$
;

CREATE OR REPLACE FUNCTION app_private.trades_recalculate_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private'
AS $function$
begin
  if tg_op in ('UPDATE','DELETE') then
    perform app_private.recalculate_position(old.customer_id,old.symbol);
    perform app_private.sync_customer_position_status(old.customer_id);
  end if;

  if tg_op in ('INSERT','UPDATE') then
    perform app_private.recalculate_position(new.customer_id,new.symbol);
    perform app_private.sync_customer_position_status(new.customer_id);
  end if;

  return coalesce(new,old);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.recalculate_position(p_customer_id bigint, p_symbol text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  v_qty numeric(20,6) := 0;
  v_avg numeric(20,6) := 0;
  v_realized numeric(20,6) := 0;
  v_total_bought numeric(20,6) := 0;
  v_total_sold numeric(20,6) := 0;
  v_market text := '';
  v_name text := null;
  v_currency text := 'USD';
begin
  for r in
    select * from public.trades
    where customer_id = p_customer_id and symbol = p_symbol
    order by traded_at asc, id asc
  loop
    v_market := r.market;
    v_name := r.stock_name;
    v_currency := r.currency;
    if r.side = 'buy' then
      if v_qty + r.quantity > 0 then
        v_avg := ((v_avg * v_qty) + (r.price * r.quantity) + r.fees) / (v_qty + r.quantity);
      end if;
      v_qty := v_qty + r.quantity;
      v_total_bought := v_total_bought + (r.price * r.quantity) + r.fees;
    else
      if r.quantity > v_qty then
        raise exception '卖出数量超过当前持仓：% > %', r.quantity, v_qty;
      end if;
      v_realized := v_realized + ((r.price - v_avg) * r.quantity) - r.fees;
      v_qty := v_qty - r.quantity;
      v_total_sold := v_total_sold + (r.price * r.quantity) - r.fees;
      if v_qty = 0 then
        v_avg := 0;
      end if;
    end if;
  end loop;

  if not exists(
    select 1 from public.trades where customer_id=p_customer_id and symbol=p_symbol
  ) then
    delete from public.positions where customer_id=p_customer_id and symbol=p_symbol;
    return;
  end if;

  insert into public.positions(
    customer_id,symbol,market,stock_name,currency,quantity,avg_cost,total_bought,total_sold,realized_pnl,updated_at
  ) values (
    p_customer_id,p_symbol,v_market,v_name,v_currency,v_qty,v_avg,v_total_bought,v_total_sold,v_realized,now()
  )
  on conflict (customer_id,symbol) do update set
    market=excluded.market,
    stock_name=excluded.stock_name,
    currency=excluded.currency,
    quantity=excluded.quantity,
    avg_cost=excluded.avg_cost,
    total_bought=excluded.total_bought,
    total_sold=excluded.total_sold,
    realized_pnl=excluded.realized_pnl,
    updated_at=now();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_customer_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare target uuid;capacity numeric;total numeric;owner uuid;enabled boolean;snapshot numeric;
begin
 target:=case when TG_OP='DELETE' then old.project_id else new.project_id end;
 owner:=case when TG_OP='DELETE' then old.owner_user_id else new.owner_user_id end;
 if owner is distinct from auth.uid() or not exists(select 1 from public.profiles where id=auth.uid() and status='active') then raise exception 'Unauthorized';end if;
 if TG_OP='UPDATE' and (new.owner_user_id<>old.owner_user_id or new.project_id<>old.project_id or new.customer_id<>old.customer_id) then raise exception 'Reservation identity is immutable';end if;
 select total_shares,customer_ledger_enabled,total_shares-remaining_shares into capacity,enabled,snapshot from public.allocation_projects where id=target and owner_user_id=auth.uid() for update;
 if capacity is null then raise exception 'Project unavailable';end if;
 if TG_OP<>'DELETE' and not exists(select 1 from public.customers where id=new.customer_id and owner_user_id=new.owner_user_id) then raise exception 'Customer does not belong to project owner';end if;
 select coalesce(sum(reserved_shares),0) into total from public.allocation_customer_reservations where project_id=target and status='confirmed' and (TG_OP='INSERT' or id<>old.id);
 if TG_OP<>'DELETE' and new.status='confirmed' then total:=total+new.reserved_shares;end if;
 if total>capacity then raise exception 'Project capacity exceeded';end if;
 if not enabled and total>snapshot then raise exception 'Historical customer details exceed reserved snapshot';end if;
 if TG_OP='DELETE' then return old;else return new;end if;
end $function$
;

CREATE OR REPLACE FUNCTION public.validate_profile_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare parent_role text;parent_status text;
begin
 if new.role='admin' then
  if new.parent_user_id is not null then raise exception 'Administrator must not have a parent';end if;
 elsif new.role='level2' then
  select role,status into parent_role,parent_status from public.profiles where id=new.parent_user_id and status<>'deleted';
  if parent_role is distinct from 'admin' then raise exception 'Secondary account requires an administrator';end if;
  if new.status='active' and parent_status is distinct from 'active' then raise exception 'Administrator is not active';end if;
 else raise exception 'Unsupported account role';end if;
 if tg_op='UPDATE' and new.status is distinct from old.status and new.status in ('disabled','deleted') then
  if new.role='level2' and exists(select 1 from public.customers where owner_user_id=new.id) then raise exception 'Transfer customers before disabling or deleting account';end if;
  if new.role='admin' and exists(select 1 from public.profiles where parent_user_id=new.id and (case when new.status='deleted' then status<>'deleted' else status='active' end)) then raise exception 'Transfer secondary accounts first';end if;
 end if;return new;
end$function$
;

CREATE OR REPLACE FUNCTION public.validate_customer_ledger_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
 if old.customer_ledger_enabled and not new.customer_ledger_enabled then raise exception 'Customer ledger cannot be disabled after activation';end if;
 if not old.customer_ledger_enabled and new.customer_ledger_enabled and (new.total_shares<>old.total_shares or new.remaining_shares<>old.remaining_shares or old.total_shares-old.remaining_shares<>(select coalesce(sum(reserved_shares),0) from public.allocation_customer_reservations where project_id=new.id and status='confirmed')) then raise exception 'Customer details must match historical reserved snapshot before activation';end if;
 if new.customer_ledger_enabled and new.total_shares<(select coalesce(sum(reserved_shares),0) from public.allocation_customer_reservations where project_id=new.id and status='confirmed') then raise exception 'Project capacity below confirmed customer reservations';end if;
 return new;
end $function$
;

