CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.save_allocation_reservation(p_project_id uuid, p_slot_at timestamp with time zone, p_reserved_shares numeric, p_participant_count integer, p_notes text DEFAULT ''::text, p_record_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare project public.allocation_projects; result_id uuid; latest_reserved numeric;
begin
 select * into project from public.allocation_projects where id=p_project_id for update;
 if project.id is null or project.owner_user_id<>auth.uid() or not public.can_read_allocation_owner(project.owner_user_id) then
  raise exception 'Not authorized' using errcode='42501';
 end if;
 if p_reserved_shares is null or p_reserved_shares<0 or p_reserved_shares>project.total_shares
 or p_participant_count is null or p_participant_count<0 or p_slot_at is null
 or (p_slot_at at time zone 'Europe/Bucharest')::date<>project.board_date
 or char_length(coalesce(p_notes,''))>2000 then
  raise exception 'Invalid reservation snapshot' using errcode='22023';
 end if;
 if p_record_id is null then
  insert into public.allocation_reservations(project_id,owner_user_id,slot_at,reserved_shares,participant_count,notes)
  values(project.id,auth.uid(),p_slot_at,p_reserved_shares,p_participant_count,coalesce(p_notes,'')) returning id into result_id;
 else
  update public.allocation_reservations set slot_at=p_slot_at,reserved_shares=p_reserved_shares,
  participant_count=p_participant_count,notes=coalesce(p_notes,''),updated_at=now()
  where id=p_record_id and project_id=project.id and owner_user_id=auth.uid() returning id into result_id;
  if result_id is null then raise exception 'Not authorized' using errcode='42501'; end if;
 end if;
 select reserved_shares into latest_reserved from public.allocation_reservations
 where project_id=project.id and (slot_at at time zone 'Europe/Bucharest')::date=project.board_date
 order by slot_at desc limit 1;
 update public.allocation_projects set remaining_shares=total_shares-latest_reserved,updated_at=now() where id=project.id;
 return result_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_customer_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare owner_role text;owner_status text;owner_parent uuid;parent_role text;parent_status text;
begin
 select role,status,parent_user_id into owner_role,owner_status,owner_parent from public.profiles where id=new.owner_user_id;
 if owner_role is distinct from 'level2' or owner_status is distinct from 'active' then raise exception 'Customer owner must be an active secondary account';end if;
 if new.level_one_user_id is null or new.level_one_user_id is distinct from owner_parent then raise exception 'Customer administrator must match owner parent';end if;
 select role,status into parent_role,parent_status from public.profiles where id=new.level_one_user_id;
 if parent_role is distinct from 'admin' or parent_status is distinct from 'active' then raise exception 'Customer administrator is not active';end if;return new;
end$function$
;

CREATE OR REPLACE FUNCTION public.trades_recalculate_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op in ('UPDATE','DELETE') then
    perform public.recalculate_position(old.customer_id, old.symbol);
  end if;
  if tg_op in ('INSERT','UPDATE') then
    perform public.recalculate_position(new.customer_id, new.symbol);
  end if;
  return coalesce(new, old);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_share_board_against_slots()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare slot_total numeric;
begin
  select coalesce(sum(reserved_shares),0) into slot_total
  from public.share_board_slots where board_id=new.id;
  if slot_total > (new.total_shares-new.remaining_shares) then
    raise exception '已录入的时段预留份额超过新的已预留总量';
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.can_access_owner(target_owner uuid, target_level_one uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'app_private'
AS $function$
 select app_private.can_access_owner(target_owner,target_level_one);
$function$
;

