;

CREATE OR REPLACE FUNCTION app_private.current_parent_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select parent_user_id
  from public.profiles
  where id=(select auth.uid())
  limit 1;
$function$
;

CREATE OR REPLACE FUNCTION public.guard_profile_self_name()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
 if current_user = 'service_role' then return new;end if;
 if exists(select 1 from public.profiles where id=auth.uid() and role='admin' and status='active') then return new;end if;
 if auth.uid() is distinct from old.id or old.status<>'active' or (to_jsonb(new)-'display_name'-'updated_at') is distinct from (to_jsonb(old)-'display_name'-'updated_at') then raise exception 'Only your display name may be changed';end if;
 if char_length(btrim(new.display_name)) not between 1 and 80 then raise exception 'Display name must contain 1 to 80 characters';end if;
 new.display_name:=btrim(new.display_name);new.updated_at:=now();return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.can_access_customer(target_customer bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists(
    select 1 from public.customers c
    where c.id = target_customer
      and public.can_access_owner(c.owner_user_id, c.level_one_user_id)
  );
$function$
;

CREATE OR REPLACE FUNCTION app_private.sync_customer_position_status(p_customer_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if exists (
    select 1 from public.positions
    where customer_id=p_customer_id and quantity>0
  ) then
    update public.customers
    set status='holding'
    where id=p_customer_id and status<>'holding';
  else
    update public.customers
    set status='following'
    where id=p_customer_id and status='holding';
  end if;
end;
$function$
;

